using UnityEngine;
public sealed class OZBot:MonoBehaviour {
 OZGame game;OZActor actor;CharacterController body;float next,vertical;Vector3 detour;float detourUntil;
 public void Init(OZGame g,OZActor a){game=g;actor=a;body=GetComponent<CharacterController>();next=Time.time+Random.Range(1f,3f);}
 void Update(){if(!actor||!game.Playing||actor.Dead||!game.Player||game.Player.Dead||game.Deploying){if(actor)actor.Pose(0,false);return;}Vector3 delta=game.Player.transform.position-transform.position;delta.y=0;float d=delta.magnitude;Vector3 dir=delta.normalized;float speed=d>13?4:0;Vector3 eye=transform.position+Vector3.up*1.55f;bool visible=false;Vector3 sight=game.Player.transform.position+Vector3.up*1.1f-eye;var hits=Physics.RaycastAll(eye,sight.normalized,sight.magnitude+.35f,~0,QueryTriggerInteraction.Ignore);System.Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));foreach(var hit in hits){if(hit.collider.GetComponentInParent<OZActor>()==actor)continue;if(hit.collider.GetComponentInParent<OZActor>()==game.Player)visible=true;else {visible=false;break;}}if(!visible)speed=4;
 if(speed>0&&Physics.SphereCast(eye,.3f,dir,out RaycastHit h,2)&&h.collider.GetComponentInParent<OZActor>()!=game.Player&&h.collider.GetComponentInParent<OZActor>()!=actor){if(Time.time>detourUntil){detour=Quaternion.Euler(0,Random.value>.5f?75:-75,0)*dir;detourUntil=Time.time+1.5f;}}if(Time.time<detourUntil)dir=detour;transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(dir.sqrMagnitude>.01f?dir:transform.forward),Time.deltaTime*8);vertical=body.isGrounded?-2:vertical-18*Time.deltaTime;body.Move((dir*speed+Vector3.up*vertical)*Time.deltaTime);actor.Pose(speed,visible&&speed==0);if(visible&&d<24&&Time.time>next){next=Time.time+Random.Range(.8f,1.5f);actor.Fire();if(Random.value<.65f)game.Player.Damage(8);}}
}
